{"command":"cd /workspace && cat > src/main.rs <<'EOF'
//! handlr — manage default applications (reimplementation).

mod cli;
mod common;
mod config;
mod apps;
mod mimedb;
mod table;
mod xdg;
mod util;

use std::io::IsTerminal;
use std::process::{Command, Stdio};

pub use common::error::{Error, Result};

fn run(apps: &mut apps::MimeApps, cmd: cli::Cmd) -> Result<()> {
    use cli::Cmd;
    match cmd {
        Cmd::Set { mime, handler } => {
            apps.set_handler(mime, handler);
            apps.save()?;
        }
        Cmd::Add { mime, handler } => {
            apps.add_handler(mime, handler);
            apps.save()?;
        }
        Cmd::Launch { mime, args } => {
            apps.get_handler(&mime)?.launch(apps, args)?;
        }
        Cmd::Get { mime, json } => {
