fn parse_char_specifiers(s: &[char]) -> Vec<CharSpec> {
    let mut cs = Vec::new();
    let mut i = 0;
    while i < s.len() {
        if i + 3 <= s.len() && s[i + 1] == '-' {
            cs.push(CharSpec::Range(s[i], s[i + 2]));
            i += 3;
        } else {
            cs.push(CharSpec::Single(s[i]));
            i += 1;
        }
    }
