impl Pattern {
    pub fn new(pattern: &str) -> std::result::Result<Pattern, PatternError> {
        let chars: Vec<char> = pattern.chars().collect();
        let mut tokens = Vec::new();
        let mut i = 0;
        while i < chars.len() {
            match chars[i] {
                '?' => {
                    tokens.push(Token::AnyChar);
                    i += 1;
                }
                '*' => {
                    let old = i;
                    while i < chars.len() && chars[i] == '*' {
                        i += 1;
                    }
                    let count = i - old;
                    if count > 2 {
                        return Err(PatternError { pos: old + 2, msg: ERROR_WILDCARDS });
                    } else if count == 2 {
                        if (i == 2 || chars[i - count - 1] == '/')
                            && (i == chars.len() || chars[i] == '/')
                        {
                            if i < chars.len() {
                                i += 1;
                            }
                            tokens.push(Token::AnyRecursiveSequence);
                        } else {
                            return Err(PatternError {
                                pos: old + 2,
                                msg: ERROR_RECURSIVE_WILDCARDS,
                            });
                        }
                    } else {
                        tokens.push(Token::AnySequence);
                    }
                }
                '[' => {
                    if i + 4 <= chars.len() && chars[i + 1] == '!' {
                        if let Some(j) = chars[i + 3..].iter().position(|x| *x == ']') {
                            let cs = parse_char_specifiers(&chars[i + 2..i + 3 + j]);
                            tokens.push(Token::AnyExcept(cs));
                            i += j + 4;
                            continue;
                        }
                    } else if i + 3 <= chars.len() && chars[i + 1] != '!' {
                        if let Some(j) = chars[i + 2..].iter().position(|x| *x == ']') {
                            let cs = parse_char_specifiers(&chars[i + 1..i + 2 + j]);
                            tokens.push(Token::AnyWithin(cs));
                            i += j + 3;
                            continue;
                        }
                    }
                    return Err(PatternError { pos: i, msg: ERROR_INVALID_RANGE });
                }
                c => {
                    tokens.push(Token::Char(c));
                    i += 1;
                }
            }
        }
        Ok(Pattern { tokens })
    }

    pub fn matches(&self, s: &str) -> bool {
        let chars: Vec<char> = s.chars().collect();
        matches_from(&self.tokens, &chars)
    }
}

fn in_specs(specs: &[CharSpec], c: char) -> bool {
    specs.iter().any(|spec| match spec {
        CharSpec::Single(s) => *s == c,
        CharSpec::Range(a, b) => *a <= c && c <= *b,
    })
}

fn matches_from(tokens: &[Token], chars: &[char]) -> bool {
    let mut ti = 0;
    let mut ci = 0;
    while ti < tokens.len() {
        match &tokens[ti] {
            Token::AnySequence | Token::AnyRecursiveSequence => {
                // try every possible split
                let rest = &tokens[ti + 1..];
                let mut k = ci;
                loop {
                    if matches_from(rest, &chars[k..]) {
                        return true;
                    }
                    if k >= chars.len() {
                        return false;
                    }
                    k += 1;
                }
            }
            tok => {
                if ci >= chars.len() {
                    return false;
                }
                let c = chars[ci];
                let ok = match tok {
                    Token::AnyChar => true,
                    Token::AnyWithin(specs) => in_specs(specs, c),
                    Token::AnyExcept(specs) => !in_specs(specs, c),
                    Token::Char(p) => *p == c,
                    _ => unreachable!(),
                };
                if !ok {
                    return false;
                }
                ti += 1;
                ci += 1;
            }
        }
    }
    ci == chars.len()
}
