//! Media type parsing following RFC 7231 token rules.

use std::fmt;
use std::hash::{Hash, Hasher};

#[derive(Clone)]
pub struct Mime {
    /// Normalized source: type, subtype and parameter names are lowercase.
    source: String,
    slash: usize,
    /// Index of the ';' starting the parameter list, if any.
    params_start: Option<usize>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParseError {
    MissingSlash,
    MissingEqual,
    MissingQuote,
    InvalidToken { pos: usize, byte: u8 },
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::MissingSlash => {
                f.write_str("a slash (/) was missing between the type and subtype")
            }
            ParseError::MissingEqual => {
                f.write_str("an equals sign (=) was missing between a parameter and its value")
            }
            ParseError::MissingQuote => {
                f.write_str("a quote (\") was missing from a parameter value")
            }
            ParseError::InvalidToken { pos, byte } => write!(
                f,
                "an invalid token was encountered, {:X} at position {}",
                byte, pos
            ),
        }
    }
}

fn is_token(c: u8) -> bool {
    matches!(c,
        b'!' | b'#' | b'$' | b'%' | b'&' | b'\'' | b'*' | b'+' | b'-' | b'.' | b'^' | b'_'
        | b'`' | b'|' | b'~' | b'0'..=b'9' | b'a'..=b'z' | b'A'..=b'Z')
}

fn is_restricted_quoted_char(c: u8) -> bool {
    c == 9 || (c > 31 && c != 127)
}

type Indexed = (usize, usize);

enum ParamSource {
    None,
    Custom(usize, Vec<(Indexed, Indexed)>),
}

impl Mime {
    pub fn parse(s: &str) -> Result<Mime, ParseError> {
        if s == "*/*" {
            return Ok(Mime { source: s.to_owned(), slash: 1, params_start: None });
        }
        let bytes = s.as_bytes();
        let mut iter = bytes.iter().copied().enumerate();

        // type
        let slash;
        let mut start;
        loop {
            match iter.next() {
                Some((_, c)) if is_token(c) => (),
                Some((i, b'/')) if i > 0 => {
                    slash = i;
                    start = i + 1;
                    break;
                }
                None => return Err(ParseError::MissingSlash),
                Some((pos, byte)) => return Err(ParseError::InvalidToken { pos, byte }),
            }
        }
        // subtype
        loop {
            match iter.next() {
                Some((i, b'+')) if i > start => {}
                Some((i, b';')) if i > start => {
                    start = i;
                    break;
                }
                Some((_, c)) if is_token(c) => (),
                None => {
                    return Ok(Mime { source: s.to_ascii_lowercase(), slash, params_start: None });
                }
                Some((pos, byte)) => return Err(ParseError::InvalidToken { pos, byte }),
            }
        }
        // params
        let params = params_from_str(s, &mut iter, start)?;
        let (source, params_start) = match params {
            ParamSource::None => (s[..start].to_ascii_lowercase(), None),
            ParamSource::Custom(semicolon, indices) => {
                let mut owned = s.to_owned();
                owned[..semicolon].make_ascii_lowercase();
                for (name, value) in &indices {
                    owned[name.0..name.1].make_ascii_lowercase();
                    if &owned[name.0..name.1] == "charset" {
                        owned[value.0..value.1].make_ascii_lowercase();
                    }
                }
                (owned, Some(semicolon))
            }
        };
        Ok(Mime { source, slash, params_start })
    }

    pub fn type_(&self) -> &str {
        &self.source[..self.slash]
    }

    pub fn subtype(&self) -> &str {
        let end = self.params_start.unwrap_or(self.source.len());
        &self.source[self.slash + 1..end]
    }

    pub fn essence_str(&self) -> &str {
        let end = self.params_start.unwrap_or(self.source.len());
        &self.source[..end]
    }

    pub fn as_str(&self) -> &str {
        &self.source
    }
}

fn params_from_str(
    s: &str,
    iter: &mut std::iter::Enumerate<impl Iterator<Item = u8>>,
    mut start: usize,
) -> Result<ParamSource, ParseError> {
    let params_start = start;
    start += 1;
    let mut params = ParamSource::None;
    'params: while start < s.len() {
        let name;
        // name
        'name: loop {
            match iter.next() {
                Some((i, b' ')) if i == start => {
                    start = i + 1;
                    continue 'name;
                }
                Some((_, c)) if is_token(c) => (),
                Some((i, b'=')) if i > start => {
                    name = (start, i);
                    start = i + 1;
                    break 'name;
                }
                None => return Err(ParseError::MissingEqual),
                Some((pos, byte)) => return Err(ParseError::InvalidToken { pos, byte }),
            }
        }
        let value;
        let mut is_quoted = false;
        'value: loop {
            if is_quoted {
                match iter.next() {
                    Some((i, b'"')) if i > start => {
                        value = (start, i);
                        break 'value;
                    }
                    Some((_, c)) if is_restricted_quoted_char(c) => (),
                    None => return Err(ParseError::MissingQuote),
                    Some((pos, byte)) => return Err(ParseError::InvalidToken { pos, byte }),
                }
            } else {
                match iter.next() {
                    Some((i, b'"')) if i == start => {
                        is_quoted = true;
                        start = i + 1;
                    }
                    Some((_, c)) if is_token(c) => (),
                    Some((i, b';')) if i > start => {
                        value = (start, i);
                        start = i + 1;
                        break 'value;
                    }
                    None => {
                        value = (start, s.len());
                        start = s.len();
                        break 'value;
                    }
                    Some((pos, byte)) => return Err(ParseError::InvalidToken { pos, byte }),
                }
            }
        }
        if is_quoted {
            'ws: loop {
                match iter.next() {
                    Some((i, b';')) => {
                        start = i + 1;
                        break 'ws;
                    }
                    Some((_, b' ')) => (),
                    None => {
                        start = s.len();
                        break 'ws;
                    }
                    Some((pos, byte)) => return Err(ParseError::InvalidToken { pos, byte }),
                }
            }
        }
        match params {
            ParamSource::Custom(_, ref mut vec) => vec.push((name, value)),
            ParamSource::None => {
                params = ParamSource::Custom(params_start, vec![(name, value)]);
            }
        }
        if start >= s.len() {
            break 'params;
        }
    }
    Ok(params)
}

impl fmt::Display for Mime {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.source)
    }
}

impl fmt::Debug for Mime {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:?}", self.source)
    }
}

impl PartialEq for Mime {
    fn eq(&self, other: &Mime) -> bool {
        self.source == other.source
    }
}

impl Eq for Mime {}

impl Hash for Mime {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.source.hash(state);
    }
}

impl PartialOrd for Mime {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Mime {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.source.cmp(&other.source)
    }
}

impl std::str::FromStr for Mime {
    type Err = ParseError;
    fn from_str(s: &str) -> Result<Mime, ParseError> {
        Mime::parse(s)
    }
}

pub const APPLICATION_OCTET_STREAM: &str = "application/octet-stream";
pub const TEXT_PLAIN: &str = "text/plain";
pub const INODE_DIRECTORY: &str = "inode/directory";
pub const APPLICATION_X_ZEROSIZE: &str = "application/x-zerosize";

pub fn mime(s: &str) -> Mime {
    Mime::parse(s).expect("static mime")
}
EOF
