/// Whether a token is one of the field codes that expand to the arguments.
fn is_special_token(arg: &str) -> bool {
    matches!(arg, "%f" | "%u" | "%F" | "%U")
}

/// Position of the first field code (`%f`, `%u`, `%F`, `%U`) in `arg`.
fn find_special(arg: &str) -> Option<usize> {
    let b = arg.as_bytes();
    (0..b.len().saturating_sub(1))
        .find(|&i| b[i] == b'%' && matches!(b[i + 1], b'f' | b'u' | b'F' | b'U'))
}

impl DesktopEntry {
    pub fn try_from_path(path: &Path) -> Result<Self> {
        let content = std::fs::read_to_string(path).map_err(|_| Error::BadEntry(path.to_owned()))?;
        let sections = parse_sections(&content).ok_or_else(|| Error::BadEntry(path.to_owned()))?;
        let attrs = sections
            .iter()
            .rev()
            .find(|(name, _)| name == "Desktop Entry")
            .map(|(_, attrs)| attrs)
            .ok_or_else(|| Error::BadEntry(path.to_owned()))?;
        let name = attrs
            .get("Name")
            .filter(|v| !v.is_empty())
            .ok_or_else(|| Error::BadEntry(path.to_owned()))?
            .clone();
        let exec = attrs
            .get("Exec")
            .filter(|v| !v.is_empty())
            .ok_or_else(|| Error::BadEntry(path.to_owned()))?
            .clone();
        let terminal = attrs.get("Terminal").map(|v| v == "true").unwrap_or(false);
        let mimes = attrs
            .get("MimeType")
            .map(|v| {
                v.split(';')
                    .filter(|s| !s.is_empty())
                    .filter_map(|s| Mime::parse(s).ok())
                    .collect()
            })
            .unwrap_or_default();
        Ok(DesktopEntry {
            name,
            exec,
            file_name: path.file_name().map(|f| f.to_owned()).unwrap_or_default(),
            terminal,
            mimes,
        })
    }

