//! A compact WHATWG-style URL parser sufficient for scheme detection,
//! normalization and `file:` path extraction.

use std::ffi::OsString;
use std::os::unix::ffi::OsStringExt;
use std::path::PathBuf;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Url {
    scheme: String,
    username: String,
    password: Option<String>,
    host: Option<String>,
    port: Option<u16>,
    /// Either a list of segments (hierarchical) or an opaque path.
    path: Path,
    query: Option<String>,
    fragment: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Path {
    Segments(Vec<String>),
    Opaque(String),
}

#[derive(Debug)]
pub struct ParseError;

fn is_special(scheme: &str) -> bool {
    matches!(scheme, "http" | "https" | "ws" | "wss" | "ftp" | "file")
}

fn default_port(scheme: &str) -> Option<u16> {
    match scheme {
        "http" | "ws" => Some(80),
        "https" | "wss" => Some(443),
        "ftp" => Some(21),
        _ => None,
    }
}

fn is_c0_control_or_space(c: char) -> bool {
    (c as u32) <= 0x20
}

fn in_c0_set(c: char) -> bool {
    (c as u32) < 0x20 || (c as u32) > 0x7E
}

fn in_fragment_set(c: char) -> bool {
    in_c0_set(c) || matches!(c, ' ' | '"' | '<' | '>' | '`')
}

fn in_query_set(c: char, special: bool) -> bool {
    in_c0_set(c) || matches!(c, ' ' | '"' | '#' | '<' | '>') || (special && c == '\'')
}

fn in_path_set(c: char) -> bool {
    in_query_set(c, false) || matches!(c, '?' | '`' | '{' | '}')
}

fn in_userinfo_set(c: char) -> bool {
    in_path_set(c) || matches!(c, '/' | ':' | ';' | '=' | '@' | '[' | '\\' | ']' | '^' | '|')
}

fn percent_encode(s: &str, pred: impl Fn(char) -> bool) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        if pred(c) {
            let mut buf = [0u8; 4];
            for b in c.encode_utf8(&mut buf).bytes() {
                out.push_str(&format!("%{:02X}", b));
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn percent_decode(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    let mut out = Vec::with_capacity(b.len());
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() + 0 && i + 2 <= b.len() - 1 + 0 {
            let h = (b[i + 1] as char).to_digit(16);
            let l = (b[i + 2] as char).to_digit(16);
            if let (Some(h), Some(l)) = (h, l) {
                out.push((h * 16 + l) as u8);
                i += 3;
                continue;
            }
        }
        out.push(b[i]);
        i += 1;
    }
    out
}

fn is_forbidden_host(c: char) -> bool {
    matches!(
        c,
        '\0' | '\t' | '\n' | '\r' | ' ' | '#' | '/' | ':' | '<' | '>' | '?' | '@' | '[' | '\\' | ']'
            | '^' | '|'
    )
}

fn is_forbidden_domain(c: char) -> bool {
    is_forbidden_host(c) || (c as u32) < 0x20 || c == '%' || c == '\u{7f}'
}

fn parse_ipv4_number(s: &str) -> Option<u64> {
    if s.is_empty() {
        return None;
    }
    let (digits, radix) = if s.len() >= 2 && (s.starts_with("0x") || s.starts_with("0X")) {
        (&s[2..], 16)
    } else if s.len() >= 2 && s.starts_with('0') {
        (&s[1..], 8)
    } else {
        (s, 10)
    };
    if digits.is_empty() {
        return Some(0);
    }
    u64::from_str_radix(digits, radix).ok()
}

fn ends_in_a_number(host: &str) -> bool {
    let mut parts: Vec<&str> = host.split('.').collect();
    if parts.last() == Some(&"") {
        if parts.len() == 1 {
            return false;
        }
        parts.pop();
    }
    let last = match parts.last() {
        Some(l) => *l,
        None => return false,
    };
    if !last.is_empty() && last.bytes().all(|b| b.is_ascii_digit()) {
        return true;
    }
    parse_ipv4_number(last).is_some() && (last.starts_with("0x") || last.starts_with("0X"))
}

fn parse_ipv4(host: &str) -> Result<String, ParseError> {
    let mut parts: Vec<&str> = host.split('.').collect();
    if parts.last() == Some(&"") && parts.len() > 1 {
        parts.pop();
    }
    if parts.len() > 4 {
        return Err(ParseError);
    }
    let mut numbers = Vec::new();
    for p in &parts {
        numbers.push(parse_ipv4_number(p).ok_or(ParseError)?);
    }
    for n in &numbers[..numbers.len() - 1] {
        if *n > 255 {
            return Err(ParseError);
        }
    }
    let last = *numbers.last().unwrap();
    if last >= 256u64.pow(5 - numbers.len() as u32) {
        return Err(ParseError);
    }
    let mut ipv4 = last;
    for (i, n) in numbers[..numbers.len() - 1].iter().enumerate() {
        ipv4 += n * 256u64.pow(3 - i as u32);
    }
    Ok(format!(
        "{}.{}.{}.{}",
        (ipv4 >> 24) & 0xff,
        (ipv4 >> 16) & 0xff,
        (ipv4 >> 8) & 0xff,
        ipv4 & 0xff
    ))
}

fn parse_ipv6(s: &str) -> Result<String, ParseError> {
    let addr: std::net::Ipv6Addr = s.parse().map_err(|_| ParseError)?;
    let segs = addr.segments();
    // find longest run of zeros (length > 1)
    let mut best: Option<(usize, usize)> = None;
    let mut i = 0;
    while i < 8 {
        if segs[i] == 0 {
            let start = i;
            while i < 8 && segs[i] == 0 {
                i += 1;
            }
            let len = i - start;
            if len > 1 && best.map(|(_, l)| len > l).unwrap_or(true) {
                best = Some((start, len));
            }
        } else {
            i += 1;
        }
    }
    let mut out = String::new();
    let mut i = 0;
    let mut ignore0 = false;
    while i < 8 {
        if let Some((start, len)) = best {
            if i == start {
                out.push_str(if i == 0 { "::" } else { ":" });
                i += len;
                ignore0 = true;
                continue;
            }
        }
        out.push_str(&format!("{:x}", segs[i]));
        if i < 7 {
            out.push(':');
        }
        i += 1;
        let _ = ignore0;
    }
    // remove a trailing ':' introduced before a compressed tail
    if out.ends_with("::") {
        // fine
    } else if out.ends_with(':') && best.map(|(s, l)| s + l == 8).unwrap_or(false) {
        // compressed run at end: already handled by "::"? ensure correct
    }
    // Simpler and reliable: rebuild using std formatting which uses RFC 5952
    Ok(format!("{}", addr))
}

/// Encode a single label with Punycode (RFC 3492).
fn punycode_encode(label: &str) -> Option<String> {
    const BASE: u32 = 36;
    const TMIN: u32 = 1;
    const TMAX: u32 = 26;
    const SKEW: u32 = 38;
    const DAMP: u32 = 700;
    const INITIAL_BIAS: u32 = 72;
    const INITIAL_N: u32 = 128;
    fn adapt(mut delta: u32, num_points: u32, first: bool) -> u32 {
        delta = if first { delta / DAMP } else { delta / 2 };
        delta += delta / num_points;
        let mut k = 0;
        while delta > ((BASE - TMIN) * TMAX) / 2 {
            delta /= BASE - TMIN;
            k += BASE;
        }
        k + (((BASE - TMIN + 1) * delta) / (delta + SKEW))
    }
    fn digit(d: u32) -> char {
        if d < 26 {
            (b'a' + d as u8) as char
        } else {
            (b'0' + (d - 26) as u8) as char
        }
    }
    let input: Vec<u32> = label.chars().map(|c| c as u32).collect();
    let mut output: String = label.chars().filter(|c| c.is_ascii()).collect();
    let b = output.len() as u32;
    let mut h = b;
    if b > 0 {
        output.push('-');
    }
    let mut n = INITIAL_N;
    let mut delta: u32 = 0;
    let mut bias = INITIAL_BIAS;
    while (h as usize) < input.len() {
        let m = *input.iter().filter(|&&c| c >= n).min()?;
        delta = delta.checked_add((m - n).checked_mul(h + 1)?)?;
        n = m;
        for &c in &input {
            if c < n {
                delta = delta.checked_add(1)?;
            }
            if c == n {
                let mut q = delta;
                let mut k = BASE;
                loop {
                    let t = if k <= bias {
                        TMIN
                    } else if k >= bias + TMAX {
                        TMAX
                    } else {
                        k - bias
                    };
                    if q < t {
                        break;
                    }
                    output.push(digit(t + (q - t) % (BASE - t)));
                    q = (q - t) / (BASE - t);
                    k += BASE;
                }
                output.push(digit(q));
                bias = adapt(delta, h + 1, h == b);
                delta = 0;
                h += 1;
            }
        }
        delta += 1;
        n += 1;
    }
    Some(output)
}

fn domain_to_ascii(domain: &str) -> Result<String, ParseError> {
    let mut labels = Vec::new();
    for label in domain.split('.') {
        let lower = label.to_lowercase();
        if lower.is_ascii() {
            labels.push(lower);
        } else {
            let enc = punycode_encode(&lower).ok_or(ParseError)?;
            labels.push(format!("xn--{}", enc));
        }
    }
    Ok(labels.join("."))
}

fn parse_host(input: &str, special: bool) -> Result<String, ParseError> {
    if input.starts_with('[') {
        if !input.ends_with(']') {
            return Err(ParseError);
        }
        return Ok(format!("[{}]", parse_ipv6(&input[1..input.len() - 1])?));
    }
    if !special {
        if input.chars().any(|c| is_forbidden_host(c)) {
            return Err(ParseError);
        }
        return Ok(percent_encode(input, in_c0_set));
    }
    let decoded = percent_decode(input);
    let domain = String::from_utf8(decoded).map_err(|_| ParseError)?;
    let ascii = domain_to_ascii(&domain)?;
    if ascii.is_empty() || ascii.chars().any(is_forbidden_domain) {
        return Err(ParseError);
    }
    if ends_in_a_number(&ascii) {
        return parse_ipv4(&ascii);
    }
    Ok(ascii)
}

fn is_single_dot(s: &str) -> bool {
    s == "." || s.eq_ignore_ascii_case("%2e")
}

fn is_double_dot(s: &str) -> bool {
    s == ".."
        || s.eq_ignore_ascii_case(".%2e")
        || s.eq_ignore_ascii_case("%2e.")
        || s.eq_ignore_ascii_case("%2e%2e")
}

impl Url {
    pub fn parse(input: &str) -> Result<Url, ParseError> {
        // strip leading/trailing C0 control or space, remove tab/newlines
        let trimmed = input.trim_matches(is_c0_control_or_space);
        let s: String = trimmed.chars().filter(|c| !matches!(c, '\t' | '\n' | '\r')).collect();
        let chars: Vec<char> = s.chars().collect();

        // scheme
        if chars.is_empty() || !chars[0].is_ascii_alphabetic() {
            return Err(ParseError);
        }
        let mut i = 1;
        while i < chars.len() && (chars[i].is_ascii_alphanumeric() || matches!(chars[i], '+' | '-' | '.')) {
            i += 1;
        }
        if i >= chars.len() || chars[i] != ':' {
            return Err(ParseError);
        }
        let scheme: String = chars[..i].iter().collect::<String>().to_ascii_lowercase();
        let rest: Vec<char> = chars[i + 1..].to_vec();
        let special = is_special(&scheme);

        let mut url = Url {
            scheme: scheme.clone(),
            username: String::new(),
            password: None,
            host: None,
            port: None,
            path: Path::Segments(Vec::new()),
            query: None,
            fragment: None,
        };

        let is_sep = |c: char| c == '/' || (special && c == '\\');

        // Split off fragment and query (they never contain the parsed separators we care about
        // except that '#'/'?' terminate the earlier components).
        let mut p = 0usize;
        if scheme == "file" {
            // file state
            if p < rest.len() && is_sep(rest[p]) {
                p += 1;
                if p < rest.len() && is_sep(rest[p]) {
                    p += 1;
                    // file host state
                    let start = p;
                    while p < rest.len() && !is_sep(rest[p]) && rest[p] != '?' && rest[p] != '#' {
                        p += 1;
                    }
                    let hostbuf: String = rest[start..p].iter().collect();
                    if hostbuf.is_empty() {
                        url.host = Some(String::new());
                    } else {
                        let h = parse_host(&hostbuf, true)?;
                        url.host = Some(if h == "localhost" { String::new() } else { h });
                    }
                    // path start state: consume one separator if present
                    if p < rest.len() && is_sep(rest[p]) {
                        p += 1;
                    }
                } else {
                    url.host = Some(String::new());
                    // single slash: path state continues from here (the slash consumed as separator)
                }
            } else {
                url.host = Some(String::new());
            }
            p = url.parse_path(&rest, p, special);
        } else if special {
            // special authority ignore slashes
            while p < rest.len() && is_sep(rest[p]) {
                p += 1;
            }
            p = url.parse_authority(&rest, p, special)?;
            if url.host.as_deref().map(|h| h.is_empty()).unwrap_or(true) {
                return Err(ParseError);
            }
            if p < rest.len() && is_sep(rest[p]) {
                p += 1;
            }
            p = url.parse_path(&rest, p, special);
        } else if p < rest.len() && rest[p] == '/' {
            p += 1;
            if p < rest.len() && rest[p] == '/' {
                p += 1;
                p = url.parse_authority(&rest, p, special)?;
                if p < rest.len() && rest[p] == '/' {
                    p += 1;
                    p = url.parse_path(&rest, p, special);
                } else {
                    url.path = Path::Segments(Vec::new());
                }
            } else {
                // path state with the leading '/' consumed as separator
                p = url.parse_path(&rest, p, special);
            }
        } else {
            // opaque path
            let start = p;
            while p < rest.len() && rest[p] != '?' && rest[p] != '#' {
                p += 1;
            }
            let opaque: String = rest[start..p].iter().collect();
            url.path = Path::Opaque(percent_encode(&opaque, in_c0_set));
        }

        // query
        if p < rest.len() && rest[p] == '?' {
            p += 1;
            let start = p;
            while p < rest.len() && rest[p] != '#' {
                p += 1;
            }
            let q: String = rest[start..p].iter().collect();
            url.query = Some(percent_encode(&q, |c| in_query_set(c, special)));
        }
        // fragment
        if p < rest.len() && rest[p] == '#' {
            p += 1;
            let f: String = rest[p..].iter().collect();
            url.fragment = Some(percent_encode(&f, in_fragment_set));
        }
        Ok(url)
    }

    fn parse_authority(&mut self, rest: &[char], mut p: usize, special: bool) -> Result<usize, ParseError> {
        let start = p;
        while p < rest.len()
            && rest[p] != '/'
            && rest[p] != '?'
            && rest[p] != '#'
            && !(special && rest[p] == '\\')
        {
            p += 1;
        }
        let auth: String = rest[start..p].iter().collect();
        let (userinfo, hostport) = match auth.rfind('@') {
            Some(at) => (Some(&auth[..at]), &auth[at + 1..]),
            None => (None, auth.as_str()),
        };
        if let Some(ui) = userinfo {
            if hostport.is_empty() {
                return Err(ParseError);
            }
            let (user, pass) = match ui.find(':') {
                Some(c) => (&ui[..c], Some(&ui[c + 1..])),
                None => (ui, None),
            };
            self.username = percent_encode(user, in_userinfo_set);
            self.password = pass.map(|p| percent_encode(p, in_userinfo_set));
        }
        // split port: last ':' outside brackets
        let (host, port) = {
            let bytes = hostport.as_bytes();
            let mut in_brackets = false;
            let mut colon = None;
            for (i, b) in bytes.iter().enumerate() {
                match b {
                    b'[' => in_brackets = true,
                    b']' => in_brackets = false,
                    b':' if !in_brackets => colon = Some(i),
                    _ => {}
                }
            }
            match colon {
                Some(c) => (&hostport[..c], Some(&hostport[c + 1..])),
                None => (hostport, None),
            }
        };
        if special && host.is_empty() {
            return Err(ParseError);
        }
        self.host = Some(if host.is_empty() {
            String::new()
        } else {
            parse_host(host, special)?
        });
        if let Some(port) = port {
            if !port.is_empty() {
                if !port.bytes().all(|b| b.is_ascii_digit()) {
                    return Err(ParseError);
                }
                let n: u32 = port.parse().map_err(|_| ParseError)?;
                if n > 65535 {
                    return Err(ParseError);
                }
                let n = n as u16;
                self.port = if default_port(&self.scheme) == Some(n) { None } else { Some(n) };
            }
        }
        Ok(p)
    }

    /// Parse hierarchical path segments starting at `p` (the first segment
    /// character). Returns the position of '?' / '#' / end.
    fn parse_path(&mut self, rest: &[char], mut p: usize, special: bool) -> usize {
        let mut segments: Vec<String> = Vec::new();
        let is_sep = |c: char| c == '/' || (special && c == '\\');
        loop {
            let start = p;
            while p < rest.len() && !is_sep(rest[p]) && rest[p] != '?' && rest[p] != '#' {
                p += 1;
            }
            let buf: String = rest[start..p].iter().collect();
            let at_sep = p < rest.len() && is_sep(rest[p]);
            if is_double_dot(&buf) {
                segments.pop();
                if !at_sep {
                    segments.push(String::new());
                }
            } else if is_single_dot(&buf) {
                if !at_sep {
                    segments.push(String::new());
                }
            } else {
                segments.push(percent_encode(&buf, in_path_set));
            }
            if at_sep {
                p += 1;
            } else {
                break;
            }
        }
        self.path = Path::Segments(segments);
        p
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn path(&self) -> String {
        match &self.path {
            Path::Opaque(s) => s.clone(),
            Path::Segments(segs) => {
                let mut out = String::new();
                for s in segs {
                    out.push('/');
                    out.push_str(s);
                }
                out
            }
        }
    }

    pub fn to_file_path(&self) -> Result<PathBuf, ()> {
        match &self.host {
            Some(h) if h.is_empty() => {}
            None => {}
            Some(_) => return Err(()),
        }
        let segs = match &self.path {
            Path::Segments(s) => s,
            Path::Opaque(_) => return Err(()),
        };
        let mut bytes: Vec<u8> = Vec::new();
        for s in segs {
            bytes.push(b'/');
            bytes.extend(percent_decode(s));
        }
        if bytes.is_empty() {
            bytes.push(b'/');
        }
        Ok(PathBuf::from(OsString::from_vec(bytes)))
    }
}

impl std::fmt::Display for Url {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}:", self.scheme)?;
        if let Some(host) = &self.host {
            f.write_str("//")?;
            if !self.username.is_empty() || self.password.is_some() {
                f.write_str(&self.username)?;
                if let Some(p) = &self.password {
                    write!(f, ":{}", p)?;
                }
                f.write_str("@")?;
            }
            f.write_str(host)?;
            if let Some(port) = self.port {
                write!(f, ":{}", port)?;
            }
        }
        f.write_str(&self.path())?;
        if let Some(q) = &self.query {
            write!(f, "?{}", q)?;
        }
        if let Some(fr) = &self.fragment {
            write!(f, "#{}", fr)?;
        }
        Ok(())
    }
}
