/// Minimal TOML reader/writer for the configuration file.
mod toml {
    use super::Config;

    pub fn basic_string(s: &str) -> String {
        let mut out = String::from("\"");
        for c in s.chars() {
            match c {
                '"' => out.push_str("\\\""),
                '\\' => out.push_str("\\\\"),
                '\n' => out.push_str("\\n"),
                '\r' => out.push_str("\\r"),
                '\t' => out.push_str("\\t"),
                '\u{08}' => out.push_str("\\b"),
                '\u{0c}' => out.push_str("\\f"),
                c if (c as u32) < 0x20 || c == '\u{7f}' => {
                    out.push_str(&format!("\\u{:04X}", c as u32))
                }
                c => out.push(c),
            }
        }
        out.push('"');
        out
    }

    /// A TOML error rendered the way the reference implementation's error
    /// type prints in debug output.
    pub struct TomlError {
        kind: String,
        at: usize,
        message: String,
        key: Vec<String>,
    }

    impl TomlError {
        fn render(&self, src: &str) -> String {
            let (line, col) = line_col(src, self.at);
            format!(
                "Error {{ inner: ErrorInner {{ kind: {}, line: Some({}), col: {}, at: Some({}), message: {:?}, key: [{}] }} }}",
                self.kind,
                line,
                col,
                self.at,
                self.message,
                self.key.iter().map(|k| format!("{:?}", k)).collect::<Vec<_>>().join(", ")
            )
        }
    }

    fn line_col(src: &str, at: usize) -> (usize, usize) {
        let at = at.min(src.len());
        let before = &src[..at];
        let line = before.matches('\n').count();
        let col = before.rsplit('\n').next().unwrap_or("").chars().count();
        (line, col)
    }

    #[derive(Debug, Clone, PartialEq)]
    enum Tok {
        Keylike(String),
        Equals,
        Period,
        Comma,
        Colon,
        Plus,
        LeftBrace,
        RightBrace,
        LeftBracket,
        RightBracket,
        Str(String),
        Newline,
        Eof,
    }

    fn describe(t: &Tok) -> &'static str {
        match t {
            Tok::Keylike(_) => "an identifier",
            Tok::Equals => "an equals",
            Tok::Period => "a period",
            Tok::Comma => "a comma",
            Tok::Colon => "a colon",
            Tok::Plus => "a plus",
            Tok::LeftBrace => "a left brace",
            Tok::RightBrace => "a right brace",
            Tok::LeftBracket => "a left bracket",
            Tok::RightBracket => "a right bracket",
            Tok::Str(_) => "a string",
            Tok::Newline => "a newline",
            Tok::Eof => "eof",
        }
    }

    struct Lexer<'a> {
        src: &'a str,
        pos: usize,
    }

    impl<'a> Lexer<'a> {
        fn peek_char(&self) -> Option<char> {
            self.src[self.pos..].chars().next()
        }

        fn skip_ws(&mut self) {
            while let Some(c) = self.peek_char() {
                if c == ' ' || c == '\t' {
                    self.pos += c.len_utf8();
                } else {
                    break;
                }
            }
        }

        fn skip_comment(&mut self) {
            if self.peek_char() == Some('#') {
                while let Some(c) = self.peek_char() {
                    if c == '\n' {
                        break;
                    }
                    self.pos += c.len_utf8();
                }
            }
        }

        /// Next token with its starting offset.
        fn next(&mut self) -> Result<(usize, Tok), TomlError> {
            self.skip_ws();
            self.skip_comment();
            let start = self.pos;
            let c = match self.peek_char() {
                None => return Ok((start, Tok::Eof)),
                Some(c) => c,
            };
            let simple = |t: Tok, l: &mut Lexer| {
                l.pos += 1;
                Ok((start, t))
            };
            match c {
                '\n' => simple(Tok::Newline, self),
                '\r' if self.src[self.pos..].starts_with("\r\n") => {
                    self.pos += 2;
                    Ok((start, Tok::Newline))
                }
                '=' => simple(Tok::Equals, self),
                '.' => simple(Tok::Period, self),
                ',' => simple(Tok::Comma, self),
                ':' => simple(Tok::Colon, self),
                '+' => simple(Tok::Plus, self),
                '{' => simple(Tok::LeftBrace, self),
                '}' => simple(Tok::RightBrace, self),
                '[' => simple(Tok::LeftBracket, self),
                ']' => simple(Tok::RightBracket, self),
                '"' => self.basic_string(start),
                '\'' => self.literal_string(start),
                c if c.is_ascii_alphanumeric() || c == '-' || c == '_' => {
                    while let Some(c) = self.peek_char() {
                        if c.is_ascii_alphanumeric() || c == '-' || c == '_' {
                            self.pos += 1;
                        } else {
                            break;
                        }
                    }
                    Ok((start, Tok::Keylike(self.src[start..self.pos].to_owned())))
                }
                c => Err(TomlError {
                    kind: format!("Unexpected({:?})", c),
                    at: start,
                    message: String::new(),
                    key: vec![],
                }),
            }
        }

        fn basic_string(&mut self, start: usize) -> Result<(usize, Tok), TomlError> {
            let multiline = self.src[self.pos..].starts_with("\"\"\"");
            self.pos += if multiline { 3 } else { 1 };
            if multiline && self.peek_char() == Some('\n') {
                self.pos += 1;
            }
            let mut out = String::new();
            loop {
                let c = match self.peek_char() {
                    None => {
                        return Err(TomlError {
                            kind: "UnterminatedString".into(),
                            at: start,
                            message: String::new(),
                            key: vec![],
                        })
                    }
                    Some(c) => c,
                };
                if multiline && self.src[self.pos..].starts_with("\"\"\"") {
                    self.pos += 3;
                    break;
                }
                if !multiline && c == '"' {
                    self.pos += 1;
                    break;
                }
                if !multiline && c == '\n' {
                    return Err(TomlError {
                        kind: "NewlineInString".into(),
                        at: self.pos,
                        message: String::new(),
                        key: vec![],
                    });
                }
                self.pos += c.len_utf8();
                if c == '\\' {
                    let e = match self.peek_char() {
                        Some(e) => e,
                        None => {
                            return Err(TomlError {
                                kind: "UnterminatedString".into(),
                                at: start,
                                message: String::new(),
                                key: vec![],
                            })
                        }
                    };
                    let epos = self.pos;
                    self.pos += e.len_utf8();
                    match e {
                        'b' => out.push('\u{08}'),
                        't' => out.push('\t'),
                        'n' => out.push('\n'),
                        'f' => out.push('\u{0c}'),
                        'r' => out.push('\r'),
                        '"' => out.push('"'),
                        '\\' => out.push('\\'),
                        'u' | 'U' => {
                            let len = if e == 'u' { 4 } else { 8 };
                            let hex = self.src.get(self.pos..self.pos + len).unwrap_or("");
                            match u32::from_str_radix(hex, 16).ok().and_then(char::from_u32) {
                                Some(ch) if hex.len() == len => {
                                    out.push(ch);
                                    self.pos += len;
                                }
                                _ => {
                                    return Err(TomlError {
                                        kind: "InvalidEscape(\'u\')".into(),
                                        at: epos,
                                        message: String::new(),
                                        key: vec![],
                                    })
                                }
                            }
                        }
                        '\n' | ' ' | '\t' if multiline => {
                            while let Some(c) = self.peek_char() {
                                if c.is_whitespace() {
                                    self.pos += c.len_utf8();
                                } else {
                                    break;
                                }
                            }
                        }
                        other => {
                            return Err(TomlError {
                                kind: format!("InvalidEscape({:?})", other),
                                at: epos,
                                message: String::new(),
                                key: vec![],
                            })
                        }
                    }
                } else {
                    out.push(c);
                }
            }
            Ok((start, Tok::Str(out)))
        }

        fn literal_string(&mut self, start: usize) -> Result<(usize, Tok), TomlError> {
            let multiline = self.src[self.pos..].starts_with("'''");
            self.pos += if multiline { 3 } else { 1 };
            if multiline && self.peek_char() == Some('\n') {
                self.pos += 1;
            }
            let mut out = String::new();
            loop {
                let c = match self.peek_char() {
                    None => {
                        return Err(TomlError {
                            kind: "UnterminatedString".into(),
                            at: start,
                            message: String::new(),
                            key: vec![],
                        })
                    }
                    Some(c) => c,
                };
                if multiline && self.src[self.pos..].starts_with("'''") {
                    self.pos += 3;
                    break;
                }
                if !multiline && c == '\'' {
                    self.pos += 1;
                    break;
                }
                if !multiline && c == '\n' {
                    return Err(TomlError {
                        kind: "NewlineInString".into(),
                        at: self.pos,
                        message: String::new(),
                        key: vec![],
                    });
                }
                self.pos += c.len_utf8();
                out.push(c);
            }
            Ok((start, Tok::Str(out)))
        }
    }

    enum Value {
        Str(String),
        Bool(bool),
        Int(String),
        Float(String),
        Other(&'static str),
    }

    fn wanted(expected: &str, found: &Tok, at: usize) -> TomlError {
        TomlError {
            kind: format!("Wanted {{ expected: {:?}, found: {:?} }}", expected, describe(found)),
            at,
            message: String::new(),
            key: vec![],
        }
    }

    /// Parse a value starting at the given token.
    fn parse_value(lx: &mut Lexer, first: (usize, Tok)) -> Result<(usize, Value), TomlError> {
        let (at, tok) = first;
        match tok {
            Tok::Str(s) => Ok((at, Value::Str(s))),
            Tok::Keylike(k) => match k.as_str() {
                "true" => Ok((at, Value::Bool(true))),
                "false" => Ok((at, Value::Bool(false))),
                "inf" | "nan" => Ok((at, Value::Float(k))),
                _ => {
                    // numbers / datetimes: gather the keylike (and possible continuation)
                    let text = k.clone();
                    if text.chars().all(|c| c.is_ascii_digit() || c == '_')
                        || text.starts_with("0x")
                        || text.starts_with("0o")
                        || text.starts_with("0b")
                    {
                        // possibly a float with a fractional part
                        if lx.peek_char() == Some('.') {
                            lx.pos += 1;
                            if let Ok((_, Tok::Keylike(f))) = lx.next() {
                                return Ok((at, Value::Float(format!("{}.{}", text, f))));
                            }
                        }
                        Ok((at, Value::Int(text)))
                    } else if text.chars().all(|c| c.is_ascii_digit() || c == '-' || c == ':' || c == 'T' || c == 'Z') && text.contains('-') {
                        Ok((at, Value::Other("datetime")))
                    } else {
                        Err(TomlError {
                            kind: "InvalidNumber".into(),
                            at,
                            message: String::new(),
                            key: vec![],
                        })
                    }
                }
            },
            Tok::Plus => {
                let (_, t) = lx.next()?;
                match t {
                    Tok::Keylike(k) => Ok((at, Value::Int(k))),
                    other => Err(wanted("a number", &other, at)),
                }
            }
            Tok::LeftBracket => {
                // array: consume until matching bracket
                let mut depth = 1;
                while depth > 0 {
                    let (p, t) = lx.next()?;
                    match t {
                        Tok::LeftBracket => depth += 1,
                        Tok::RightBracket => depth -= 1,
                        Tok::Eof => return Err(wanted("a right bracket", &Tok::Eof, p)),
                        _ => {}
                    }
                }
                Ok((at, Value::Other("sequence")))
            }
            Tok::LeftBrace => {
                let mut depth = 1;
                while depth > 0 {
                    let (p, t) = lx.next()?;
                    match t {
                        Tok::LeftBrace => depth += 1,
                        Tok::RightBrace => depth -= 1,
                        Tok::Eof => return Err(wanted("a right brace", &Tok::Eof, p)),
                        _ => {}
                    }
                }
                Ok((at, Value::Other("map")))
            }
            other => Err(wanted("a value", &other, at)),
        }
    }

    fn type_error(found: String, expected: &str, at: usize, key: &str) -> TomlError {
        TomlError {
            kind: "Custom".into(),
            at,
            message: format!("invalid type: {}, expected {}", found, expected),
            key: vec![key.to_owned()],
        }
    }

    fn describe_value(v: &Value) -> String {
        match v {
            Value::Str(s) => format!("string {:?}", s),
            Value::Bool(b) => format!("boolean `{}`", b),
            Value::Int(i) => format!("integer `{}`", i.replace('_', "")),
            Value::Float(f) => format!("floating point `{}`", f),
            Value::Other(o) => o.to_string(),
        }
    }

    pub fn parse_config(src: &str) -> Result<Config, String> {
        parse_inner(src).map_err(|e| e.render(src))
    }

    fn parse_inner(src: &str) -> Result<Config, TomlError> {
        let mut lx = Lexer { src, pos: 0 };
        let mut cfg = Config::default();
        let mut seen: Vec<String> = Vec::new();
        let mut in_table = false;
        loop {
            let (at, tok) = lx.next()?;
            match tok {
                Tok::Eof => break,
                Tok::Newline => continue,
                Tok::LeftBracket => {
                    // table header: consume to the closing bracket(s)
                    loop {
                        let (p, t) = lx.next()?;
                        match t {
                            Tok::RightBracket => break,
                            Tok::Eof | Tok::Newline => {
                                return Err(wanted("a right bracket", &t, p))
                            }
                            _ => {}
                        }
                    }
                    if lx.peek_char() == Some(']') {
                        lx.pos += 1;
                    }
                    let (p, t) = lx.next()?;
                    if !matches!(t, Tok::Newline | Tok::Eof) {
                        return Err(wanted("newline", &t, p));
                    }
                    in_table = true;
                }
                Tok::Keylike(_) | Tok::Str(_) => {
                    let mut key = match &tok {
                        Tok::Keylike(k) => k.clone(),
                        Tok::Str(s) => s.clone(),
                        _ => unreachable!(),
                    };
                    let mut dotted = false;
                    // dotted keys
                    let (mut p, mut t) = lx.next()?;
                    while t == Tok::Period {
                        dotted = true;
                        let (_, part) = lx.next()?;
                        match part {
                            Tok::Keylike(k) => key = format!("{}.{}", key, k),
                            Tok::Str(s) => key = format!("{}.{}", key, s),
                            other => return Err(wanted("a table key", &other, p)),
                        }
                        let n = lx.next()?;
                        p = n.0;
                        t = n.1;
                    }
                    if t != Tok::Equals {
                        return Err(wanted("an equals", &t, p));
                    }
                    let first = lx.next()?;
                    if matches!(first.1, Tok::Newline | Tok::Eof) {
                        return Err(wanted("a value", &first.1, first.0));
                    }
                    let (vat, value) = parse_value(&mut lx, first)?;
                    if !in_table && !dotted {
                        if seen.contains(&key) {
                            return Err(TomlError {
                                kind: format!("DuplicateKey {{ key: {:?}, table: None }}", key),
                                at,
                                message: String::new(),
                                key: vec![],
                            });
                        }
                        seen.push(key.clone());
                        match key.as_str() {
                            "enable_selector" => match value {
                                Value::Bool(b) => cfg.enable_selector = b,
                                v => {
                                    return Err(type_error(describe_value(&v), "a boolean", vat, &key))
                                }
                            },
                            "selector" => match value {
                                Value::Str(s) => cfg.selector = s,
                                v => {
                                    return Err(type_error(describe_value(&v), "a string", vat, &key))
                                }
                            },
                            _ => {}
                        }
                    }
                    let (p, t) = lx.next()?;
                    if !matches!(t, Tok::Newline | Tok::Eof) {
                        return Err(wanted("newline", &t, p));
                    }
                }
                other => return Err(wanted("a table key", &other, at)),
            }
        }
        Ok(cfg)
    }
}
