use crate::common::{DesktopEntry, Handler, Mime};
use std::collections::{HashMap, HashSet};
use std::ffi::OsString;

/// Applications discovered from `.desktop` files in the XDG data directories.
pub struct SystemApps(pub HashMap<Mime, Vec<Handler>>);

impl SystemApps {
    pub fn populate() -> Self {
        let mut map: HashMap<Mime, Vec<Handler>> = HashMap::new();
        let mut seen: HashSet<OsString> = HashSet::new();
        for dir in crate::xdg::all_data_dirs() {
            let dir = dir.join("applications");
            let rd = match std::fs::read_dir(&dir) {
                Ok(rd) => rd,
                Err(_) => continue,
            };
            for entry in rd.flatten() {
                let path = entry.path();
                let file_name = match path.file_name() {
                    Some(f) => f.to_owned(),
                    None => continue,
                };
                if !seen.insert(file_name.clone()) {
                    continue;
                }
                if !crate::xdg::is_desktop_file(&path) {
                    continue;
                }
                if let Ok(entry) = DesktopEntry::try_from_path(&path) {
                    for mime in entry.mimes {
                        map.entry(mime)
                            .or_default()
                            .push(Handler::assume_valid(entry.file_name.clone()));
                    }
                }
            }
        }
        SystemApps(map)
    }

    pub fn get_handler(&self, mime: &Mime) -> Option<Handler> {
        self.0.get(mime).and_then(|h| h.first().cloned())
    }
}
