//! Parser for `mimeapps.list` with PEG-style error reporting.

use std::fmt;

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
#[allow(non_camel_case_types)]
pub enum Rule {
    EOI,
    file,
    section_char,
    name_char,
    value_char,
    section,
    name,
    entry,
    handlers,
    handler,
    comment,
}

/// A parse error carrying the furthest failure position and the rules that
/// were attempted there.
pub struct ParseError {
    pub positives: Vec<Rule>,
    pub pos: usize,
    pub line_col: (usize, usize),
    pub line: String,
}

impl fmt::Debug for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let positives = self
            .positives
            .iter()
            .map(|r| format!("{:?}", r))
            .collect::<Vec<_>>()
            .join(", ");
        write!(
            f,
            "Error {{ variant: ParsingError {{ positives: [{}], negatives: [] }}, location: Pos({}), line_col: Pos(({}, {})), path: None, line: {:?}, continued_line: None }}",
            positives, self.pos, self.line_col.0, self.line_col.1, self.line
        )
    }
}

#[derive(Debug, Clone)]
pub enum Item {
    Section(String),
    Entry(String, String),
}

struct State<'i> {
    input: &'i str,
    pos: usize,
    attempt_pos: usize,
    pos_attempts: Vec<Rule>,
    items: Vec<Item>,
}

impl<'i> State<'i> {
    fn attempts_at(&self, pos: usize) -> usize {
        if self.attempt_pos == pos {
            self.pos_attempts.len()
        } else {
            0
        }
    }

    fn track(&mut self, rule: Rule, pos: usize, index: usize, prev_attempts: usize) {
        let curr = self.attempts_at(pos);
        if curr > prev_attempts && curr - prev_attempts == 1 {
            return;
        }
        if pos == self.attempt_pos {
            self.pos_attempts.truncate(index);
        }
        if pos > self.attempt_pos {
            self.pos_attempts.clear();
            self.attempt_pos = pos;
        }
        if pos == self.attempt_pos {
            self.pos_attempts.push(rule);
        }
    }

    fn rule<F: FnOnce(&mut Self) -> bool>(&mut self, rule: Rule, f: F) -> bool {
        let actual_pos = self.pos;
        let index = if actual_pos == self.attempt_pos {
            self.pos_attempts.len()
        } else {
            0
        };
        let attempts = self.attempts_at(actual_pos);
        let items_len = self.items.len();
        let ok = f(self);
        if !ok {
            self.track(rule, actual_pos, index, attempts);
            self.pos = actual_pos;
            self.items.truncate(items_len);
        }
        ok
    }

    fn peek(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn match_char<F: Fn(char) -> bool>(&mut self, pred: F) -> bool {
        match self.peek() {
            Some(c) if pred(c) => {
                self.pos += c.len_utf8();
                true
            }
            _ => false,
        }
    }

    fn match_str(&mut self, s: &str) -> bool {
        if self.input[self.pos..].starts_with(s) {
            self.pos += s.len();
            true
        } else {
            false
        }
    }

    fn newline(&mut self) -> bool {
        self.match_str("\n") || self.match_str("\r\n") || self.match_str("\r")
    }

    fn end_of_input(&mut self) -> bool {
        self.rule(Rule::EOI, |s| s.pos == s.input.len())
    }

    fn section_char(&mut self) -> bool {
        self.rule(Rule::section_char, |s| s.match_char(is_section_char))
    }

    fn name_char(&mut self) -> bool {
        self.rule(Rule::name_char, |s| s.match_char(is_name_char))
    }

    fn value_char(&mut self) -> bool {
        self.rule(Rule::value_char, |s| s.match_char(is_value_char))
    }

    fn section(&mut self) -> bool {
        self.rule(Rule::section, |s| {
            if !s.match_str("[") {
                return false;
            }
            let start = s.pos;
            if !s.section_char() {
                return false;
            }
            while s.section_char() {}
            let name = s.input[start..s.pos].to_owned();
            if !s.match_str("]") {
                return false;
            }
            s.items.push(Item::Section(name));
            true
        })
    }

    fn name(&mut self) -> bool {
        self.rule(Rule::name, |s| {
            if !s.name_char() {
                return false;
            }
            while s.name_char() {}
            true
        })
    }

    fn handler(&mut self) -> bool {
        self.rule(Rule::handler, |s| {
            if !s.value_char() {
                return false;
            }
            while s.value_char() {}
            true
        })
    }

    fn handlers(&mut self) -> bool {
        self.rule(Rule::handlers, |s| {
            if !(s.handler() || s.match_str(";")) {
                return false;
            }
            while s.handler() || s.match_str(";") {}
            true
        })
    }

    fn entry(&mut self) -> bool {
        self.rule(Rule::entry, |s| {
            let start = s.pos;
            if !s.name() {
                return false;
            }
            let name = s.input[start..s.pos].to_owned();
            if !s.match_str("=") {
                return false;
            }
            let vstart = s.pos;
            if !s.handlers() {
                return false;
            }
            let value = s.input[vstart..s.pos].to_owned();
            s.items.push(Item::Entry(name, value));
            true
        })
    }

    fn comment(&mut self) -> bool {
        self.rule(Rule::comment, |s| {
            if !s.match_str("#") {
                return false;
            }
            loop {
                let save = s.pos;
                if s.newline() {
                    s.pos = save;
                    break;
                }
                if !s.match_char(|_| true) {
                    break;
                }
            }
            true
        })
    }

    fn file(&mut self) -> bool {
        self.rule(Rule::file, |s| {
            loop {
                let save = s.pos;
                let items_len = s.items.len();
