//! The user's `mimeapps.list` and handler resolution.

use super::mimeapps_parser::{self, Item};
use super::SystemApps;
use crate::common::{Handler, Mime, MimeType};
use crate::{Error, Result};
use std::collections::HashMap;
use std::io::Write;
use std::path::PathBuf;

pub struct MimeApps {
    pub added_associations: HashMap<Mime, Vec<Handler>>,
    pub default_apps: HashMap<Mime, Vec<Handler>>,
    pub system_apps: SystemApps,
}

fn mimeapps_path() -> PathBuf {
    crate::xdg::config_home().join("mimeapps.list")
}

fn read_or_create(path: &PathBuf) -> std::io::Result<String> {
    match std::fs::read_to_string(path) {
        Ok(s) => Ok(s),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            if let Some(dir) = path.parent() {
                std::fs::create_dir_all(dir)?;
            }
            std::fs::File::create(path)?;
            Ok(String::new())
        }
        Err(e) => Err(e),
    }
}

fn dedup(handlers: Vec<Handler>) -> Vec<Handler> {
    let mut out: Vec<Handler> = Vec::with_capacity(handlers.len());
    for h in handlers {
        if !out.contains(&h) {
            out.push(h);
        }
    }
    out
}

impl MimeApps {
    pub fn read() -> Self {
        let path = mimeapps_path();
        let content = match read_or_create(&path) {
            Ok(c) => c,
            Err(e) => crate::util::fake_panic(
                "src/apps/user.rs:12:65",
                &format!("called `Result::unwrap()` on an `Err` value: Io({:?})", e),
            ),
        };
        let items = match mimeapps_parser::parse(&content) {
            Ok(items) => items,
            Err(e) => crate::util::fake_panic(
                "src/apps/user.rs:12:65",
                &format!("called `Result::unwrap()` on an `Err` value: ParseApps({:?})", e),
            ),
        };

        let mut added_associations = HashMap::new();
        let mut default_apps = HashMap::new();
        let mut current: Option<String> = None;
        for item in items {
            match item {
                Item::Section(name) => current = Some(name),
                Item::Entry(name, value) => {
                    let map = match current.as_deref() {
                        Some("Default Applications") => &mut default_apps,
                        Some("Added Associations") => &mut added_associations,
                        _ => continue,
                    };
                    let mime = match Mime::parse(&name) {
                        Ok(m) => m,
                        Err(_) => continue,
                    };
                    let handlers: Vec<Handler> = value
                        .split(';')
                        .filter(|s| !s.is_empty())
                        .filter_map(|s| s.parse::<Handler>().ok())
                        .collect();
                    let handlers = dedup(handlers);
                    if handlers.is_empty() {
                        continue;
                    }
                    map.insert(mime, handlers);
                }
            }
        }

        MimeApps {
            added_associations,
            default_apps,
            system_apps: SystemApps::populate(),
        }
    }

    pub fn save(&self) -> Result<()> {
        let mut f = std::fs::File::create(mimeapps_path())?;
        let mut out = String::new();
        out.push_str("[Added Associations]\n");
        for (mime, handlers) in sorted(&self.added_associations) {
            out.push_str(&format_line(mime, handlers));
        }
        out.push_str("\n[Default Applications]\n");
        for (mime, handlers) in sorted(&self.default_apps) {
            out.push_str(&format_line(mime, handlers));
        }
        f.write_all(out.as_bytes())?;
        Ok(())
    }

    pub fn set_handler(&mut self, mime: MimeType, handler: Handler) {
        self.default_apps.insert(mime.0, vec![handler]);
    }

    pub fn add_handler(&mut self, mime: MimeType, handler: Handler) {
        self.default_apps.entry(mime.0).or_default().push(handler);
    }

    pub fn remove_handler(&mut self, mime: &MimeType) -> Result<()> {
        if self.default_apps.remove(&mime.0).is_some() {
            self.save()?;
        }
        Ok(())
    }

    fn select_with(&self, handlers: &[Handler]) -> Result<Handler> {
        let entries: Vec<(Handler, String)> = handlers
            .iter()
            .filter_map(|h| h.get_entry().ok().map(|e| (h.clone(), e.name)))
            .collect();
        let names = entries
            .iter()
            .map(|(_, n)| n.as_str())
            .collect::<Vec<_>>()
            .join("\n");
        let (prog, args) = crate::config::get().selector_cmd();
        let mut child = std::process::Command::new(prog)
            .args(args)
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .spawn()?;
        if let Some(mut stdin) = child.stdin.take() {
            let _ = stdin.write_all(names.as_bytes());
        }
        let output = child.wait_with_output()?;
        let selected = String::from_utf8(output.stdout)?;
        let selected = selected.trim_end();
        match entries.into_iter().find(|(_, n)| n == selected) {
            Some((h, _)) => Ok(h),
            None => crate::util::fake_panic(
                "src/apps/user.rs:67:26",
                "called `Option::unwrap()` on a `None` value",
            ),
        }
    }

