//! Box-drawing table rendering with a fixed maximum width of 80 columns.

const MAX_WIDTH: usize = 80;

fn char_len(s: &str) -> usize {
    s.chars().count()
}

fn fit(cell: &str, width: usize) -> String {
    let len = char_len(cell);
    if len > width {
        let mut s: String = cell.chars().take(width.saturating_sub(1)).collect();
        s.push('+');
        s
    } else {
        let mut s = cell.to_owned();
        for _ in len..width {
            s.push(' ');
        }
        s
    }
}

fn border(widths: &[usize], left: char, mid: char, right: char) -> String {
    let mut s = String::new();
    s.push(left);
    for (i, w) in widths.iter().enumerate() {
        if i > 0 {
            s.push(mid);
        }
        for _ in 0..(w + 2) {
            s.push('─');
        }
    }
    s.push(right);
    s.push('\n');
    s
}

/// Render rows of two columns.
pub fn render(rows: &[[String; 2]]) -> String {
    if rows.is_empty() {
        return "┌──┐\n│  │\n└──┘\n".to_owned();
    }
    let ncols = 2;
    let mut widths = vec![0usize; ncols];
    for row in rows {
        for (i, cell) in row.iter().enumerate() {
            widths[i] = widths[i].max(char_len(cell));
        }
    }
    let total = |w: &[usize]| w.iter().sum::<usize>() + 3 * ncols + 1;
    while total(&widths) > MAX_WIDTH {
        // shrink the widest column (the last one on ties)
        let mut idx = 0;
        for i in 0..ncols {
            if widths[i] >= widths[idx] {
                idx = i;
            }
        }
        if widths[idx] == 0 {
            break;
        }
        widths[idx] -= 1;
    }
    let mut out = String::new();
    out.push_str(&border(&widths, '┌', '┬', '┐'));
    for row in rows {
        out.push('│');
        for (i, cell) in row.iter().enumerate() {
            if i > 0 {
                out.push('│');
            }
            out.push(' ');
            out.push_str(&fit(cell, widths[i]));
            out.push(' ');
        }
        out.push('│');
        out.push('\n');
    }
    out.push_str(&border(&widths, '└', '┴', '┘'));
    out
}
EOF
