//! Reader for the shared-mime-info database (globs and magic) and the
//! mime type guessing logic built on top of it.

use crate::common::mime::{
    mime, Mime, APPLICATION_OCTET_STREAM, APPLICATION_X_ZEROSIZE, INODE_DIRECTORY, TEXT_PLAIN,
};
use crate::util::Pattern;
use std::path::Path;
use std::sync::OnceLock;

enum GlobKind {
    Literal,
    Suffix(String),
    Full(Pattern),
}

struct Glob {
    weight: u32,
    mime: Mime,
    pattern: String,
    case_sensitive: bool,
    kind: GlobKind,
}

impl Glob {
    fn new(weight: u32, mime: Mime, pattern: String, case_sensitive: bool) -> Glob {
        let has_wild = |s: &str| s.contains(['*', '?', '[']);
        let kind = if !has_wild(&pattern) {
            GlobKind::Literal
        } else if pattern.starts_with('*') && !has_wild(&pattern[1..]) {
            GlobKind::Suffix(pattern[1..].to_owned())
        } else {
            match Pattern::new(&pattern) {
                Ok(p) => GlobKind::Full(p),
                Err(e) => crate::util::fake_panic(
                    "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/xdg-mime-0.3.3/src/glob.rs:38:55",
                    &format!("called `Result::unwrap()` on an `Err` value: {:?}", e),
                ),
            }
        };
        Glob { weight, mime, pattern, case_sensitive, kind }
    }

    fn matches(&self, name: &str) -> bool {
        match &self.kind {
            GlobKind::Literal => name.to_lowercase() == self.pattern.to_lowercase(),
            GlobKind::Suffix(suffix) => {
                if self.case_sensitive {
                    name.ends_with(suffix.as_str())
                } else {
                    name.ends_with(suffix.as_str()) || name.to_lowercase().ends_with(suffix.as_str())
                }
            }
            GlobKind::Full(p) => p.matches(name),
        }
    }
}

struct MagicMatch {
    offset: usize,
    value: Vec<u8>,
    mask: Option<Vec<u8>>,
    range: usize,
    children: Vec<MagicMatch>,
}

impl MagicMatch {
    fn extent(&self) -> usize {
        let own = self.offset + self.value.len() + self.range;
        self.children.iter().map(|c| c.extent()).fold(own, usize::max)
    }

    fn matches(&self, data: &[u8]) -> bool {
        let len = self.value.len();
        let mut found = false;
        for start in self.offset..self.offset + self.range {
            if start + len > data.len() {
                break;
            }
            let slice = &data[start..start + len];
            let ok = match &self.mask {
                Some(mask) => slice
                    .iter()
                    .zip(self.value.iter())
                    .zip(mask.iter())
                    .all(|((d, v), m)| d & m == v & m),
                None => slice == self.value.as_slice(),
            };
            if ok {
                found = true;
                break;
            }
        }
        if !found {
            return false;
        }
        self.children.is_empty() || self.children.iter().any(|c| c.matches(data))
    }
}

struct MagicRule {
    priority: u32,
    mime: Mime,
    matches: Vec<MagicMatch>,
}

pub struct MimeDb {
    globs: Vec<Glob>,
    magic: Vec<MagicRule>,
    max_extent: usize,
}

static DB: OnceLock<MimeDb> = OnceLock::new();

pub fn db() -> &'static MimeDb {
    DB.get_or_init(MimeDb::load)
}

impl MimeDb {
    fn load() -> MimeDb {
        let mut db = MimeDb { globs: Vec::new(), magic: Vec::new(), max_extent: 0 };
        for dir in crate::xdg::all_data_dirs() {
            let mime_dir = dir.join("mime");
            db.load_globs(&mime_dir);
            db.load_magic(&mime_dir.join("magic"));
        }
        db.max_extent = db
            .magic
            .iter()
            .flat_map(|r| r.matches.iter().map(|m| m.extent()))
            .max()
            .unwrap_or(0);
        db
    }

    fn load_globs(&mut self, mime_dir: &Path) {
        if let Ok(content) = std::fs::read_to_string(mime_dir.join("globs2")) {
            for line in content.lines() {
                if line.starts_with('#') {
                    continue;
                }
                let parts: Vec<&str> = line.split(':').collect();
                if parts.len() < 3 {
                    continue;
                }
                let weight = match parts[0].parse::<u32>() {
                    Ok(w) => w,
                    Err(_) => continue,
                };
                let mime = match Mime::parse(parts[1]) {
                    Ok(m) => m,
                    Err(_) => continue,
                };
                let cs = parts.len() > 3 && parts[3].split(',').any(|f| f == "cs");
                self.globs.push(Glob::new(weight, mime, parts[2].to_owned(), cs));
            }
        } else if let Ok(content) = std::fs::read_to_string(mime_dir.join("globs")) {
            for line in content.lines() {
                if line.starts_with('#') {
                    continue;
                }
                let parts: Vec<&str> = line.split(':').collect();
                if parts.len() < 2 {
                    continue;
                }
                let mime = match Mime::parse(parts[0]) {
                    Ok(m) => m,
                    Err(_) => continue,
                };
                self.globs.push(Glob::new(50, mime, parts[1].to_owned(), false));
            }
        }
    }

    fn load_magic(&mut self, path: &Path) {
        let data = match std::fs::read(path) {
            Ok(d) => d,
            Err(_) => return,
        };
        const HEADER: &[u8] = b"MIME-Magic\0\n";
        if !data.starts_with(HEADER) {
            return;
        }
        let mut pos = HEADER.len();
        let mut current: Option<(MagicRule, Vec<(usize, MagicMatch)>)> = None;
        let mut rules: Vec<MagicRule> = Vec::new();
        let flush = |cur: Option<(MagicRule, Vec<(usize, MagicMatch)>)>, rules: &mut Vec<MagicRule>| {
            if let Some((mut rule, flat)) = cur {
                rule.matches = build_tree(flat);
                rules.push(rule);
            }
        };
        while pos < data.len() {
            if data[pos] == b'[' {
                let end = match data[pos..].iter().position(|&b| b == b'\n') {
                    Some(e) => pos + e,
                    None => break,
                };
                let header = &data[pos + 1..end];
                let header = header.strip_suffix(b"]").unwrap_or(header);
                let header = String::from_utf8_lossy(header);
                flush(current.take(), &mut rules);
                if let Some((prio, m)) = header.split_once(':') {
                    if let (Ok(prio), Ok(m)) = (prio.parse::<u32>(), Mime::parse(m)) {
                        current = Some((MagicRule { priority: prio, mime: m, matches: Vec::new() }, Vec::new()));
                    }
                }
                pos = end + 1;
            } else {
