//! Command line parsing with clap-2 compatible output.

use crate::common::{Handler, MimeType, UserPath};
use std::process::exit;

pub enum Cmd {
    List { all: bool },
    Open { paths: Vec<UserPath> },
    Set { mime: MimeType, handler: Handler },
    Unset { mime: MimeType },
    Launch { mime: MimeType, args: Vec<String> },
    Get { mime: MimeType, json: bool },
    Add { mime: MimeType, handler: Handler },
}

const VERSION: &str = "0.6.4";

struct Positional {
    display: &'static str,
    required: bool,
    multiple: bool,
}

struct Flag {
    short: Option<char>,
    long: &'static str,
}

struct SubSpec {
    name: &'static str,
    about: &'static str,
    positionals: &'static [Positional],
    flags: &'static [Flag],
    /// Help text for the flags section (already formatted).
    flags_help: &'static str,
}

const SUBS: &[SubSpec] = &[
    SubSpec {
        name: "list",
        about: "List default apps and the associated handlers",
        positionals: &[],
        flags: &[Flag { short: Some('a'), long: "all" }],
        flags_help: "    -a, --all        \n",
    },
    SubSpec {
        name: "open",
        about: "Open a path/URL with its default handler",
        positionals: &[Positional { display: "<paths>...", required: true, multiple: true }],
        flags: &[],
        flags_help: "",
    },
    SubSpec {
        name: "set",
