            Positional { display: "<handler>", required: true, multiple: false },
        ],
        flags: &[],
        flags_help: "",
    },
];

fn bin_name() -> String {
    std::env::args_os()
        .next()
        .and_then(|a| {
            std::path::Path::new(&a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
        })
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "handlr".to_owned())
}

