    let mut s = String::new();
    s.push_str(&format!("handlr {}\n\nUSAGE:\n    {} <SUBCOMMAND>\n\n", VERSION, bin));
    s.push_str("FLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\n");
