/// Usage line listing required positionals followed by the given flags.
fn smart_usage(bin: &str, sub: Option<&SubSpec>, used: &[String]) -> String {
    let mut s = bin.to_owned();
    if let Some(sub) = sub {
        s.push(' ');
        s.push_str(sub.name);
        for p in sub.positionals {
            if p.required {
                s.push(' ');
                s.push_str(p.display);
            }
        }
    }
    for u in used {
        s.push(' ');
        s.push_str(u);
    }
    s
}

fn usage_with(bin: &str, sub: Option<&SubSpec>, used: &[String]) -> String {
    if used.is_empty() {
        match sub {
            Some(sub) => sub_usage(bin, sub),
            None => format!("{} <SUBCOMMAND>", bin),
        }
    } else {
        smart_usage(bin, sub, used)
    }
}

fn sub_help(bin: &str, sub: &SubSpec) -> String {
    let mut s = format!("{}-{} \n{}\n\nUSAGE:\n    {}\n\n", bin, sub.name, sub.about, sub_usage(bin, sub));
    if !sub.positionals.is_empty() {
        s.push_str("ARGS:\n");
        let width = sub.positionals.iter().map(|p| p.display.len()).max().unwrap_or(0);
        for p in sub.positionals {
            s.push_str(&format!("    {:<w$}    \n", p.display, w = width));
        }
        s.push('\n');
    }
    s.push_str("FLAGS:\n");
    s.push_str(sub.flags_help);
    s.push_str("    -h, --help       Prints help information\n    -V, --version    Prints version information\n");
    s
}

fn error_exit(msg: &str) -> ! {
    eprintln!("{}", msg);
    exit(2);
}

fn unknown_argument(arg: &str, did_you_mean: &str, usage: &str) -> ! {
    let dym = if did_you_mean.is_empty() {
        format!("\n\nIf you tried to supply `{}` as a PATTERN use `-- {}`", arg, arg)
    } else {
        format!("{}\n", did_you_mean)
    };
    error_exit(&format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context{}\n\nUSAGE:\n    {}\n\nFor more information try --help",
        arg, dym, usage
    ));
}

fn unexpected_multiple(arg: &str, usage: &str) -> ! {
    error_exit(&format!(
        "error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help",
        arg, usage
    ));
}

fn missing_required(names: &[&str], usage: &str) -> ! {
    let mut list = String::new();
    for n in names {
        list.push_str(&format!("    {}\n", n));
    }
    error_exit(&format!(
        "error: The following required arguments were not provided:\n{}\nUSAGE:\n    {}\n\nFor more information try --help",
        list, usage
    ));
}

fn empty_value(name: &str, usage: &str) -> ! {
    error_exit(&format!(
        "error: The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help",
        name, usage
    ));
}

fn invalid_value(name: &str, msg: &str) -> ! {
    error_exit(&format!(
        "error: Invalid value for '{}': {}\n\nFor more information try --help",
        name, msg
    ));
}

/// Long flag suggestion for an unknown `--arg` within the given command.
fn flag_did_you_mean(bin: &str, sub: Option<&SubSpec>, name: &str, used: &[String]) -> (String, String) {
    let mut longs: Vec<&str> = vec!["help", "version"];
    if let Some(sub) = sub {
        longs.extend(sub.flags.iter().map(|f| f.long));
    }
    if let Some(cand) = crate::util::did_you_mean(name, &longs) {
        let mut used_now: Vec<String> = used.to_vec();
        let flag = format!("--{}", cand);
        if !used_now.contains(&flag) {
            used_now.push(flag.clone());
        }
        let dym = format!("\n\n\tDid you mean '{}'?\n", flag);
        return (dym, smart_usage(bin, sub, &used_now));
    }
    if sub.is_none() {
        // suggest a subcommand flag
        for s in SUBS {
            let subs_longs: Vec<&str> = s.flags.iter().map(|f| f.long).collect();
            if let Some(cand) = crate::util::did_you_mean(name, &subs_longs) {
                let dym = format!(
                    "\n\n\tDid you mean to put '--{}' after the subcommand '{}'?\n",
                    cand, s.name
                );
                return (dym, usage_with(bin, None, used));
            }
        }
    }
    (String::new(), usage_with(bin, sub, used))
}

pub fn parse() -> Cmd {
    let bin = bin_name();
    let args: Vec<String> = std::env::args_os()
        .skip(1)
        .map(|a| a.to_string_lossy().into_owned())
        .collect();

    let mut iter = args.iter().peekable();
    let mut saw_double_dash = false;
    while let Some(arg) = iter.next() {
        if !saw_double_dash && arg == "--" {
            saw_double_dash = true;
            continue;
        }
        if !saw_double_dash && arg.starts_with("--") {
            let name = arg.trim_start_matches('-');
            let name = name.split('=').next().unwrap_or("");
            match name {
                "help" => {
                    print!("{}", main_help(&bin));
                    exit(0);
                }
                "version" => {
                    println!("handlr {}", VERSION);
                    exit(0);
                }
                _ => {
                    let (dym, usage) = flag_did_you_mean(&bin, None, name, &[]);
                    unknown_argument(&format!("--{}", name), &dym, &usage);
                }
            }
        }
        if !saw_double_dash && arg.starts_with('-') && arg.len() > 1 {
            for c in arg[1..].chars() {
                match c {
                    'h' => {
                        print!("{}", main_help(&bin));
                        exit(0);
                    }
                    'V' => {
                        println!("handlr {}", VERSION);
                        exit(0);
                    }
                    other => {
                        let usage = usage_with(&bin, None, &[]);
                        unknown_argument(&format!("-{}", other), "", &usage);
                    }
                }
            }
            continue;
        }
        // positional: subcommand
        if saw_double_dash || SUBS.iter().all(|s| s.name != arg.as_str()) {
            let names: Vec<&str> = SUBS.iter().map(|s| s.name).collect();
            if !saw_double_dash {
                if let Some(cand) = crate::util::did_you_mean(arg, &names) {
                    error_exit(&format!(
                        "error: The subcommand '{}' wasn't recognized\n\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'\n\nUSAGE:\n    {} <SUBCOMMAND>\n\nFor more information try --help",
                        arg, cand, bin, arg, bin
                    ));
                }
            }
            unknown_argument(arg, "", &format!("{} <SUBCOMMAND>", bin));
        }
        let sub = SUBS.iter().find(|s| s.name == arg.as_str()).unwrap();
        let rest: Vec<String> = iter.cloned().collect();
        return parse_sub(&bin, sub, &rest);
    }
    // no subcommand given
    eprint!("{}", main_help(&bin));
    exit(2);
}

fn parse_sub(bin: &str, sub: &SubSpec, args: &[String]) -> Cmd {
    let mut values: Vec<Vec<String>> = vec![Vec::new(); sub.positionals.len()];
    let mut flags_set: Vec<bool> = vec![false; sub.flags.len()];
    let mut used: Vec<String> = Vec::new();
    let mut pos_index = 0usize;
    let mut saw_double_dash = false;

    let mut set_flag = |i: usize, flags_set: &mut Vec<bool>, used: &mut Vec<String>| {
        let long = format!("--{}", sub.flags[i].long);
        if flags_set[i] {
            unexpected_multiple(&long, &usage_with(bin, Some(sub), used));
        }
        flags_set[i] = true;
        used.push(long);
    };

    for arg in args {
        if !saw_double_dash && arg == "--" {
            saw_double_dash = true;
            continue;
        }
        if !saw_double_dash && arg.starts_with("--") {
            let name = arg.trim_start_matches('-');
            let name = name.split('=').next().unwrap_or("");
            match name {
                "help" => {
                    print!("{}", sub_help(bin, sub));
                    exit(0);
                }
                "version" => {
                    println!("{}-{} ", bin, sub.name);
                    exit(0);
                }
                _ => {
                    if let Some(i) = sub.flags.iter().position(|f| f.long == name) {
                        set_flag(i, &mut flags_set, &mut used);
                        continue;
                    }
                    let (dym, usage) = flag_did_you_mean(bin, Some(sub), name, &used);
                    unknown_argument(&format!("--{}", name), &dym, &usage);
                }
            }
        }
        if !saw_double_dash && arg.starts_with('-') && arg.len() > 1 {
            for c in arg[1..].chars() {
                match c {
                    'h' => {
                        print!("{}", sub_help(bin, sub));
                        exit(0);
                    }
                    'V' => {
                        println!("{}-{} ", bin, sub.name);
                        exit(0);
                    }
                    other => {
                        if let Some(i) = sub.flags.iter().position(|f| f.short == Some(other)) {
                            set_flag(i, &mut flags_set, &mut used);
                        } else {
                            let usage = usage_with(bin, Some(sub), &used);
                            unknown_argument(&format!("-{}", other), "", &usage);
                        }
                    }
                }
            }
            continue;
        }
        // positional value
        if pos_index >= sub.positionals.len() {
            let usage = usage_with(bin, Some(sub), &used);
            unknown_argument(arg, "", &usage);
        }
        values[pos_index].push(arg.clone());
        if !sub.positionals[pos_index].multiple {
            pos_index += 1;
        }
    }

    // required arguments
    let missing: Vec<&str> = sub
        .positionals
        .iter()
        .enumerate()
        .filter(|(i, p)| p.required && values[*i].is_empty())
        .map(|(_, p)| p.display)
        .collect();
    if !missing.is_empty() {
        missing_required(&missing, &usage_with(bin, Some(sub), &used));
    }

    // value validation, in command line order
    for (i, p) in sub.positionals.iter().enumerate() {
        for v in &values[i] {
            if v.is_empty() {
                empty_value(p.display, &usage_with(bin, Some(sub), &[]));
            }
        }
    }

    let mut parsed_mimes: Vec<MimeType> = Vec::new();
    let mut parsed_handlers: Vec<Handler> = Vec::new();
    let mut parsed_paths: Vec<UserPath> = Vec::new();
    for (i, p) in sub.positionals.iter().enumerate() {
        for v in &values[i] {
            match p.display {
                "<mime>" => match v.parse::<MimeType>() {
                    Ok(m) => parsed_mimes.push(m),
                    Err(e) => invalid_value(p.display, &e.to_string()),
                },
                "<handler>" => match v.parse::<Handler>() {
                    Ok(h) => parsed_handlers.push(h),
                    Err(e) => invalid_value(p.display, &e.to_string()),
                },
                "<paths>..." => match v.parse::<UserPath>() {
                    Ok(p) => parsed_paths.push(p),
                    Err(e) => invalid_value(p.display, &e.to_string()),
                },
                _ => {}
            }
        }
    }

    match sub.name {
        "list" => Cmd::List { all: flags_set[0] },
        "open" => Cmd::Open { paths: parsed_paths },
        "set" => Cmd::Set { mime: parsed_mimes.remove(0), handler: parsed_handlers.remove(0) },
        "unset" => Cmd::Unset { mime: parsed_mimes.remove(0) },
        "launch" => Cmd::Launch { mime: parsed_mimes.remove(0), args: values[1].clone() },
        "get" => Cmd::Get { mime: parsed_mimes.remove(0), json: flags_set[0] },
        "add" => Cmd::Add { mime: parsed_mimes.remove(0), handler: parsed_handlers.remove(0) },
        _ => unreachable!(),
    }
}
